add_action( 'woocommerce_product_query', 'perfectpixel_hide_category_from_shop' );

function perfectpixel_hide_category_from_shop( $q ) {
	$ids = wp_parse_id_list( '{{shop_hidden_category_ids}}' );
	if ( ! $ids ) {
		return;
	}
	$on_shop   = is_shop() && ! is_search();
	$on_search = is_search() && 'yes' === '{{shop_hidden_in_search}}';
	if ( ! $on_shop && ! $on_search ) {
		return;
	}
	$tax_query   = (array) $q->get( 'tax_query' );
	$tax_query[] = array(
		'taxonomy' => 'product_cat',
		'field'    => 'term_id',
		'terms'    => $ids,
		'operator' => 'NOT IN',
	);
	$q->set( 'tax_query', $tax_query );
}
